package io.github.miklires.mcodes;import java.util.*;public record RedemptionResult(Status status,UUID transactionId,CodeDefinition definition){public enum Status{ACCEPTED,NOT_FOUND,NOT_STARTED,EXPIRED,LIMIT_REACHED,ALREADY_USED,IDENTITY_LIMIT,SELF_REFERRAL,SAME_IDENTITY,NO_PERMISSION,NOT_ENOUGH_PLAYTIME}public static RedemptionResult rejected(Status s){return new RedemptionResult(s,null,null);}}
